<?php
declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado','docente');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$p=db();$s=$p->prepare("SELECT t.*,tr.nombre turno,CONCAT(d.nombre,' ',d.apellido) docente,CONCAT(en.nombre,' ',en.apellido) encargado,s.nombre sala,s.ubicacion,e.codigo_inventario FROM tickets t JOIN usuarios d ON d.id=t.docente_id JOIN turnos tr ON tr.id=t.turno_id LEFT JOIN usuarios en ON en.id=t.encargado_id JOIN salas s ON s.id=t.sala_id LEFT JOIN equipos e ON e.id=t.equipo_id WHERE t.id=:id");$s->execute(['id'=>$id]);$t=$s->fetch();if(!$t||(is_docente()&&(int)$t['docente_id']!==(int)current_user()['id'])||(is_encargado()&&(int)$t['turno_id']!==manager_turn_id())){http_response_code(404);require __DIR__.'/404.php';exit;}$s=$p->prepare("SELECT c.comentario,c.creado_en,CONCAT(u.nombre,' ',u.apellido) autor,u.rol FROM comentarios_ticket c JOIN usuarios u ON u.id=c.usuario_id WHERE c.ticket_id=:id ORDER BY c.creado_en");$s->execute(['id'=>$id]);$comments=$s->fetchAll();$s=$p->prepare("SELECT l.accion,l.detalle,l.creado_en,COALESCE(CONCAT(u.nombre,' ',u.apellido),'Sistema') usuario FROM log_actividad l LEFT JOIN usuarios u ON u.id=l.usuario_id WHERE l.entidad='tickets' AND l.entidad_id=:id ORDER BY l.creado_en");$s->execute(['id'=>$id]);$events=$s->fetchAll();$pageTitle='Ticket #'.(int)$t['id'];require __DIR__.'/includes/header.php';$flow=['abierto','en_revision','en_proceso','resuelto','cerrado'];$currentIndex=array_search($t['estado'],$flow,true);?>
<section class="ticket-progress card"><div class="card-body"><div class="progress-track"><?php foreach($flow as $i=>$st):?><div class="progress-step <?=$i<=$currentIndex?'is-done':''?> <?=$i===$currentIndex?'is-current':''?>"><span><?=$i+1?></span><strong><?=e(ucwords(str_replace('_',' ',$st)))?></strong></div><?php endforeach;?></div></div></section>
<section class="grid grid-2 mt-3"><article class="card"><div class="card-header"><h2><?=e(ucwords(str_replace('_',' ',$t['tipo_problema'])))?></h2><?=status_badge($t['estado'])?></div><div class="card-body"><div class="grid grid-2"><div><strong>Docente</strong><div><?=e($t['docente'])?></div></div><div><strong>Turno</strong><div><?=e($t['turno'])?></div></div><div><strong>Urgencia</strong><div><?=status_badge($t['urgencia'])?></div></div><div><strong>Sala</strong><div><a href="<?=e(url('sala.php?id='.(int)$t['sala_id']))?>"><?=e($t['sala'])?></a></div></div><div><strong>Equipo</strong><div><?=e($t['codigo_inventario']??'-')?></div></div><div><strong>Creado</strong><div><?=e(format_datetime($t['creado_en']))?></div></div><div><strong>Responsable</strong><div><?=e($t['encargado']??'Sin asignar')?></div></div><?php if($t['resuelto_en']):?><div><strong>Resuelto</strong><div><?=e(format_datetime($t['resuelto_en']))?></div></div><?php endif;?></div><h3>Descripción</h3><div class="ticket-message"><?=e($t['descripcion'])?></div><?php if($t['foto']):?><h3>Imagen adjunta</h3><a href="<?=e(url($t['foto']))?>" target="_blank"><img class="photo-preview" src="<?=e(url($t['foto']))?>" alt="Foto del problema"></a><?php endif;?></div></article>
<aside class="grid"><?php if(is_encargado()):?><article class="card"><div class="card-header"><h2>Gestionar ticket</h2></div><div class="card-body"><form action="<?=e(url('php/ticket_actualizar.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><div class="form-group"><label>Estado</label><select name="estado"><?php foreach($flow as $v):?><option value="<?=e($v)?>" <?=$t['estado']===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="form-group mt-2"><label>Urgencia</label><select name="urgencia"><?php foreach(['baja','media','alta','critica'] as $v):?><option value="<?=e($v)?>" <?=$t['urgencia']===$v?'selected':''?>><?=e(ucfirst($v))?></option><?php endforeach;?></select></div><div class="form-actions"><button class="btn btn-primary">Actualizar</button></div></form></div></article><?php endif;?>
<article class="card"><div class="card-header"><h2>Historial del ticket</h2></div><div class="card-body"><?php if(!$events):?><p class="text-muted">Sin movimientos registrados.</p><?php else:?><ol class="ticket-timeline"><?php foreach($events as $ev):?><li><span></span><div><strong><?=e($ev['accion'])?></strong><p><?=e($ev['detalle']??'')?></p><small><?=e($ev['usuario'].' · '.format_datetime($ev['creado_en']))?></small></div></li><?php endforeach;?></ol><?php endif;?></div></article>
<article class="card"><div class="card-header"><h2>Comentarios</h2></div><div class="card-body"><?php if(!$comments):?><p class="text-muted">No hay comentarios.</p><?php else:?><ul class="list-clean"><?php foreach($comments as $c):?><li><strong><?=e($c['autor'])?></strong> <span class="badge badge-neutral"><?=e(ucfirst($c['rol']))?></span><p class="ticket-message"><?=e($c['comentario'])?></p><div class="meta"><?=e(format_datetime($c['creado_en']))?></div></li><?php endforeach;?></ul><?php endif;?><form class="mt-3" action="<?=e(url('php/comentario_guardar.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><div class="form-group"><label>Nuevo comentario</label><textarea name="comentario" maxlength="2000" required></textarea></div><div class="form-actions"><button class="btn btn-secondary">Agregar comentario</button></div></form></div></article></aside></section><?php require __DIR__.'/includes/footer.php';?>
